// src/pages/AdminPanel.jsx
import React, { useEffect, useState } from "react";
import { getAuth } from "firebase/auth";
import {
  getFirestore,
  doc,
  getDoc,
  collection,
  getDocs,
  query,
  where
} from "firebase/firestore";
import { app } from "../firebase-config";
import { useNavigate } from "react-router-dom";
import Dashboard from "./Dashboard"; // If you have a dashboard/task UI

const auth = getAuth(app);
const db = getFirestore(app);

function AdminPanel() {
  const [users, setUsers] = useState([]);
  const [selectedUserTasks, setSelectedUserTasks] = useState([]);
  const [selectedUserEmail, setSelectedUserEmail] = useState("");
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);

  const navigate = useNavigate();

  useEffect(() => {
    const checkAdminAndFetchUsers = async () => {
      const currentUser = auth.currentUser;

      if (!currentUser) {
        navigate("/login");
        return;
      }

      let isAdminUser = false;

      try {
        const userRef = doc(db, "users", currentUser.uid);
        const userSnap = await getDoc(userRef);

        if (userSnap.exists()) {
          const userData = userSnap.data();
          if (userData.role === "admin") {
            isAdminUser = true;
          }
        }

        // Fallback to hardcoded email check
        if (currentUser.email === "shailiesd@gmail.com") {
          isAdminUser = true;
        }

        setIsAdmin(isAdminUser);

        if (isAdminUser) {
          const usersRef = collection(db, "users");
          const snapshot = await getDocs(usersRef);
          const userList = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          }));
          setUsers(userList);
        }
      } catch (error) {
        console.error("Admin check or user fetch failed:", error);
      }

      setLoading(false);
    };

    checkAdminAndFetchUsers();
  }, [navigate]);

  const handleViewTasks = async (userId, userEmail) => {
    try {
      const tasksRef = collection(db, "tasks");
      const q = query(tasksRef, where("uid", "==", userId));
      const snapshot = await getDocs(q);
      const tasks = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setSelectedUserTasks(tasks);
      setSelectedUserEmail(userEmail);
    } catch (error) {
      console.error("Error fetching user tasks:", error);
    }
  };

  if (loading) return <p>Loading...</p>;
  if (!isAdmin) return <p>You do not have permission to view this page.</p>;

  return (
    <div style={{ padding: "2rem" }}>
      <h2>Admin Panel</h2>
      <p>This is the admin area. Only visible to admin users.</p>

      <h3>Manage Users:</h3>
      <ul>
        {users.length === 0 ? (
          <p>No users found in Firestore.</p>
        ) : (
          users.map((user) => (
            <li key={user.id}>
              <strong>{user.email}</strong> ({user.role || "user"}){" "}
              <button onClick={() => handleViewTasks(user.id, user.email)}>
                View Tasks
              </button>
            </li>
          ))
        )}
      </ul>

      {selectedUserTasks.length > 0 && (
        <div style={{ marginTop: "2rem" }}>
          <h4>Tasks of {selectedUserEmail}</h4>
          <ul>
            {selectedUserTasks.map((task) => (
              <li key={task.id}>
                {task.title} — {task.priority || "No priority"}
              </li>
            ))}
          </ul>
        </div>
      )}

      {/* Admin's Own Task Section */}
      <div style={{ marginTop: "2rem" }}>
        <h3>Your Own Tasks:</h3>
        <Dashboard /> {/* Replace with actual task input component if needed */}
      </div>
    </div>
  );
}

export default AdminPanel;
