import React, { useContext, useState, useEffect, createContext } from "react";
import { getAuth, onAuthStateChanged, signOut } from "firebase/auth";
import { doc, getDoc, getFirestore } from "firebase/firestore";
import { app } from "../firebase-config";

const auth = getAuth(app);
const db = getFirestore(app);

const AuthContext = createContext();

export function useAuth() {
  return useContext(AuthContext);
}

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState(false);
  const [userName, setUserName] = useState(""); // ✅ Store the name here

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      setUser(user);
      
      if (user) {
        // ✅ Check if admin
        if (user.email === "shailiesd@gmail.com") {
          setIsAdmin(true);
        } else {
          setIsAdmin(false);
        }

        // ✅ Fetch user name from Firestore
        try {
          const userDocRef = doc(db, "users", user.uid);
          const userDocSnap = await getDoc(userDocRef);

          if (userDocSnap.exists()) {
            const data = userDocSnap.data();
            setUserName(data.name || ""); // use name if available
          } else {
            setUserName(""); // no doc found
            console.warn("User document not found in Firestore.");
          }
        } catch (error) {
          console.error("Error fetching user name:", error);
        }
      } else {
        setIsAdmin(false);
        setUserName(""); // clear on logout
      }

      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const logout = () => signOut(auth);

  const value = {
    user,
    loading,
    isAdmin,
    logout,
    userName, // ✅ expose userName
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}
