// Enhanced Dashboard.jsx with Notifications, Heatmap, Drag-and-Drop, Admin Visibility
import { getAuth, signOut } from "firebase/auth";
import { useNavigate } from "react-router-dom";
import { useEffect, useState, useRef } from "react";
import CalendarHeatmap from "react-calendar-heatmap";
import "react-calendar-heatmap/dist/styles.css";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";
import Calendar from "react-calendar";
import "react-calendar/dist/Calendar.css";
import {
  collection,
  query,
  where,
  getDocs,
  addDoc,
  deleteDoc,
  updateDoc,
  doc,
  serverTimestamp,
} from "firebase/firestore";
import { useAuth } from "../auth/AuthContext";
import { db } from "../firebase-config";
import "./Dashboard.css";

function Dashboard() {
  const { user, isAdmin } = useAuth();
  const navigate = useNavigate();
  const handleLogout = () => {
  const auth = getAuth();
  signOut(auth)
    .then(() => {
      navigate("/login");
    })
    .catch((error) => {
      console.error("Logout failed:", error);
    });
};
  const [userName, setUserName] = useState("");
  const [tasks, setTasks] = useState([]);
  const [taskInput, setTaskInput] = useState("");
  const [priority, setPriority] = useState("Low");
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [reminderTime, setReminderTime] = useState("");
  const [editingTaskId, setEditingTaskId] = useState(null);
  const reminderInterval = useRef(null);

  const fetchTasks = async () => {
    if (!user) return;
    const q = isAdmin
      ? query(collection(db, "tasks"))
      : query(collection(db, "tasks"), where("uid", "==", user.uid));
    const querySnapshot = await getDocs(q);
    const fetched = querySnapshot.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
      date: doc.data().timestamp?.toDate() || new Date(), // ✅ Ensure consistent valid date
    }));
    setTasks(fetched);
  };

  useEffect(() => {
    fetchTasks();
  }, [user]);


useEffect(() => {
  const fetchUserName = async () => {
    if (!user) return;

    try {
      const usersRef = collection(db, "users");
      const q = query(usersRef, where("uid", "==", user.uid));
      const querySnapshot = await getDocs(q);

      if (!querySnapshot.empty) {
        const userData = querySnapshot.docs[0].data();
        console.log("Fetched user data:", userData); // debug
        if (userData.name) {
          setUserName(userData.name);
        } else {
          console.warn("No 'name' field found in user document.");
        }
      } else {
        console.warn("No user document found for UID:", user.uid);
      }
    } catch (err) {
      console.error("Error fetching user name:", err);
    }
  };


  fetchUserName();
}, [user]);

  useEffect(() => {
    if (reminderInterval.current) clearInterval(reminderInterval.current);
    reminderInterval.current = setInterval(() => {
      const now = new Date();
      tasks.forEach((task) => {
        if (
          task.reminder &&
          new Date(task.date).toDateString() === now.toDateString()
        ) {
          const [hours, minutes] = task.reminder.split(":").map(Number);
          const taskTime = new Date(task.date);
          taskTime.setHours(hours, minutes, 0, 0);
          const timeDiff = taskTime - now;
          if (timeDiff > 0 && timeDiff < 60000) {
            alert(`Reminder: ${task.title}`);
          }
        }
      });
    }, 30000);
    return () => clearInterval(reminderInterval.current);
  }, [tasks]);

  const handleAddTask = async (e) => {
    e.preventDefault();
    if (!taskInput.trim()) return;
    const taskData = {
      uid: user.uid,
      title: taskInput,
      priority,
      timestamp: selectedDate,
      reminder: reminderTime,
      createdAt: serverTimestamp(),
    };
    try {
      if (editingTaskId) {
        await updateDoc(doc(db, "tasks", editingTaskId), taskData);
        setEditingTaskId(null);
      } else {
        await addDoc(collection(db, "tasks"), taskData);
      }
      setTaskInput("");
      setReminderTime("");
      fetchTasks();
    } catch (error) {
      console.error("Error saving task:", error);
    }
  };

  const handleDelete = async (id) => {
    await deleteDoc(doc(db, "tasks", id));
    fetchTasks();
  };

  const handleEdit = (task) => {
    setTaskInput(task.title);
    setPriority(task.priority);
    setReminderTime(task.reminder || "");
    setSelectedDate(task.date);
    setEditingTaskId(task.id);
  };

  const handleDragEnd = async (result) => {
    if (!result.destination) return;
    const items = Array.from(tasks);
    const [reorderedItem] = items.splice(result.source.index, 1);
    items.splice(result.destination.index, 0, reorderedItem);
    setTasks(items);
  };

  const getPriorityColor = (priority) => {
    switch (priority) {
      case "High":
        return "#f44336";
      case "Medium":
        return "#ff9800";
      case "Low":
        return "#4caf50";
      default:
        return "#9e9e9e";
    }
  };

  const filteredTasks = tasks.filter(
    (task) =>
      task.date &&
      new Date(task.date).toDateString() ===
        new Date(selectedDate).toDateString()
  );

const seenDates = new Map();
tasks.forEach((task) => {
  const dateStr = task.date instanceof Date
    ? task.date.toISOString().split("T")[0]
    : new Date(task.date).toISOString().split("T")[0];
  if (!seenDates.has(dateStr)) {
    seenDates.set(dateStr, 1);
  } else {
    seenDates.set(dateStr, seenDates.get(dateStr) + 1);
  }
});

const heatmapData = Array.from(seenDates.entries()).map(([date, count]) => ({
  date,
  count,
}));


 return (
  <div className="dashboard">

    {/* Admin Panel (floating) */}
    {isAdmin && (
      <div className="admin-panel">
        <h3>🛠 Admin Panel</h3>
        <p>This is the admin area. Only visible to admin users.</p>
        <h4>👥 Manage Users:</h4>
        <ul>
          {user && (
  <li>{user.email} (admin) <button>View Tasks</button></li>
)}

        </ul>
      </div>
    )}

<div className="dashboard-header" style={{
  display: "flex",
  justifyContent: "space-between",
  alignItems: "center",
  marginBottom: "1rem"
}}>
  <h2>Welcome, {userName || "User"}</h2>
  <button onClick={handleLogout} style={{
    padding: "0.5rem 1rem",
    backgroundColor: "#9f9c98",
    color: "white",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer"
  }}>
    Log Out
  </button>
</div>


    {/* Main Two-Column Layout */}
    <div className="dashboard-grid">
      {/* Left: Square Calendar */}
      <div className="calendar-section">
        <Calendar
          value={selectedDate}
          onChange={setSelectedDate}
          className="custom-calendar"
        />
      </div>

      {/* Right: Add Task and Scheduled Tasks */}
      <div className="right-section">
      <div className="form-section" style={{ height: "120px", width: "455px",  
	  overflowY: "auto", minHeight: "120px", maxHeight: "120px",  margin: "0"}}>
        <h3>{editingTaskId ? "✏️ Edit Task" : "➕ Add Task"}</h3>
          <form onSubmit={handleAddTask} className="task-form">
            <input
              type="text"
              value={taskInput}
              onChange={(e) => setTaskInput(e.target.value)}
              placeholder="Enter task"
              required
            />
            <select value={priority} onChange={(e) => setPriority(e.target.value)}>
              <option>Low</option>
              <option>Medium</option>
              <option>High</option>
            </select>
            <input
              type="time"
              value={reminderTime}
              onChange={(e) => setReminderTime(e.target.value)}
            />
            <button type="submit">{editingTaskId ? "Update" : "Add"}</button>
          </form>
        </div>
		
    <div className="task-list-section"style={{
    height: "950px",
    overflowY: "auto",
    minHeight: "250px",
    maxHeight: "350px",
    marginTop: "-900px",          // 👈 lowered from 10px to 4px
    padding: "10px",
    border: "1px solid #ccc",
    borderRadius: "8px",
    backgroundColor: "#f9f9f9",
    display: "flex",
    flexDirection: "column"}}>
    <h4 className="task-heading">🗓 Tasks on {selectedDate.toDateString()}</h4>
          <DragDropContext onDragEnd={handleDragEnd}>
            <Droppable droppableId="taskList">
              {(provided) => (
                <ul {...provided.droppableProps} ref={provided.innerRef} className="task-list">
                  {filteredTasks.map((task, index) => (
                    <Draggable key={task.id} draggableId={task.id} index={index}>
                      {(provided) => (
                        <li
                          ref={provided.innerRef}
                          {...provided.draggableProps}
                          {...provided.dragHandleProps}
                          className="task-item"
                          style={{
                            ...provided.draggableProps.style,
                            borderLeft: `6px solid ${getPriorityColor(task.priority)}`,
                          }}
                        >
                          <div>
                            <strong>{task.title}</strong> ({task.priority})
                            {task.reminder && <div>⏰ Reminder: {task.reminder}</div>}
                          </div>
                          <div className="task-actions">
                            <button onClick={() => handleEdit(task)}>Edit</button>
                            <button onClick={() => handleDelete(task.id)}>Delete</button>
                          </div>
                        </li>
                      )}
                    </Draggable>
                  ))}
                  {provided.placeholder}
                </ul>
              )}
            </Droppable>
          </DragDropContext>
        </div>
      </div>
    </div>
  </div>
);
}

export default Dashboard;
